  ('m08', '{"id":"m08","title":"8. Essais, mise en service & Qualité","icon":"✅","short":"Rinçage, désinfection, essais de pression, contrôles","content":[],"quiz":[],"finalQuiz":[{"q":"Dans quels types de réseaux intervient principalement le canalisateur ?","answers":["Uniquement plomberie intérieure","Assainissement et adduction d’eau potable","Uniquement électricité","Uniquement voirie sèche"],"correct":1},{"q":"Sous la responsabilité de qui travaille généralement le canalisateur ?","answers":["Du maire","Du chef de chantier","Du client final uniquement","De l’architecte"],"correct":1},{"q":"Combien de blocs de compétences composent le Titre Professionnel Canalisateur ?","answers":["2","3","4","5"],"correct":1},{"q":"Le métier de canalisateur s’exerce principalement :","answers":["En intérieur uniquement","En extérieur, sur chantier","Derrière un bureau","En laboratoire"],"correct":1},{"q":"Quel niveau correspond au Titre Professionnel Canalisateur ?","answers":["Niveau 2","Niveau 3 (CAP/BEP)","Niveau 5 (BTS)","Niveau 6"],"correct":1},{"q":"Que signifie AIPR ?","answers":["Autorisation d’Intervention à Proximité des Réseaux","Attestation d’Installation de Protections Rapides","Autorisation Interne de Pose de Réseaux","Accréditation d’Intervention sur Parcelles Rurales"],"correct":0},{"q":"À partir de quelle profondeur un blindage de tranchée est-il généralement obligatoire ?","answers":["0,80 m","1,30 m","2,00 m","3,00 m"],"correct":1},{"q":"Que signifie CACES ?","answers":["Certificat d’Aptitude à la Conduite En Sécurité","Contrôle Annuel de Conformité des Engins","Carte d’Aptitude à la Conduite des Engins de Sol","Certificat d’Autorisation de Conduite des Engins Spéciaux"],"correct":0},{"q":"Quel est le danger n°1 en tranchée ?","answers":["Le bruit","L’éboulement","La pluie","La chaleur"],"correct":1},{"q":"Parmi ces EPI, lequel est indispensable sur un chantier de canalisation ?","answers":["Casque et chaussures de sécurité","Cravate","Sandales","Short uniquement"],"correct":0},{"q":"Quel document doit être consulté avant d’ouvrir le sol ?","answers":["Le plan de prévention uniquement","Le DIC (Déclaration d’Intention de Commencement de travaux)","Le registre du personnel","Le bon de commande des tuyaux"],"correct":1},{"q":"Quel outil est particulièrement utile pour contrôler la pente ?","answers":["Un simple mètre ruban","Un niveau laser ou optique","Une équerre de maçon","Un dynamomètre"],"correct":1},{"q":"Que signifie implanter un réseau ?","answers":["Le peindre en couleur","Repérer et tracer sa position au sol selon les plans","Le détruire","Le photographier uniquement"],"correct":1},{"q":"Pourquoi vérifier la concordance plans / terrain ?","answers":["Par habitude","Pour éviter les erreurs d’implantation et les conflits de réseaux","Pour gagner du temps uniquement","Ce n’est pas nécessaire"],"correct":1},{"q":"Parmi ces documents, lequel décrit le profil en altitude du réseau ?","answers":["Le profil en long","Le registre du personnel","Le planning des congés","Le catalogue fournisseur"],"correct":0},{"q":"Quelle couche se place directement sous et autour de la canalisation ?","answers":["Le remblai final","Le lit de pose / enrobage","La couche de forme","Le géotextile seul"],"correct":1},{"q":"Quelle est une cause fréquente de tassements ultérieurs ?","answers":["Un compactage insuffisant du remblai","Une pente trop forte","L’utilisation de PVC","La présence d’un regard"],"correct":0},{"q":"Pourquoi organiser le balisage et la signalisation ?","answers":["Pour faire joli","Pour la sécurité des travailleurs et des usagers","Ce n’est pas obligatoire","Uniquement pour les photos"],"correct":1},{"q":"Que doit-on contrôler sur le fond de fouille ?","answers":["Uniquement la couleur du sol","Stabilité, profondeur, largeur et pente","Uniquement la largeur","Rien de particulier"],"correct":1},{"q":"Les couches de remblai doivent être compactées :","answers":["Une seule fois à la fin","À chaque couche successive","Jamais","Uniquement s’il pleut"],"correct":1},{"q":"Que se passe-t-il si la pente d’un réseau gravitaire est trop faible ?","answers":["Le débit devient trop important","Des dépôts se forment dans la canalisation","La pression augmente dangereusement","Les joints se desserrent"],"correct":1},{"q":"Dans quel sens doit-on poser les tuyaux à emboîtement ?","answers":["Dans n’importe quel sens","Dans le sens de l’écoulement","Contre le sens de l’écoulement","Verticalement uniquement"],"correct":1},{"q":"Quel matériau est particulièrement léger et économique en assainissement ?","answers":["Fonte","PVC","Béton armé uniquement","Acier"],"correct":1},{"q":"Pourquoi contrôler l’alignement et la pente pendant la pose ?","answers":["Pour l’esthétique","Pour assurer un bon écoulement et éviter les contre-pentes","Ce n’est pas important","Uniquement pour les photos"],"correct":1},{"q":"Les joints doivent être protégés pendant :","answers":["Le transport uniquement","Le remblai","La peinture","Le stockage en magasin uniquement"],"correct":1},{"q":"Quel est le rôle principal d’un regard de visite ?","answers":["Augmenter la pression","Permettre l’accès pour inspection et curage","Filtrer les eaux usées","Mesurer le débit en continu"],"correct":1},{"q":"Que désigne la « cunette » dans un regard ?","answers":["Le tampon de fermeture","Le fond façonné pour guider l’écoulement","La paroi latérale","Le système de ventilation"],"correct":1},{"q":"Où place-t-on généralement les regards de visite ?","answers":["Uniquement en bout de réseau","Aux changements de direction, de pente ou de diamètre","Au hasard","Uniquement sous les maisons"],"correct":1},{"q":"Pourquoi cartographier les branchements particuliers ?","answers":["Pour la décoration","Pour faciliter l’entretien et les interventions futures","Ce n’est pas utile","Uniquement pour la facturation"],"correct":1},{"q":"Le tampon de regard doit être choisi selon :","answers":["La couleur du sol","La classe de circulation (voiture, poids lourd…)","Le goût du client uniquement","La météo"],"correct":1},{"q":"Quel matériau est particulièrement adapté aux zones difficiles grâce à sa flexibilité ?","answers":["PVC","Fonte ductile","PeHD","Béton"],"correct":2},{"q":"Que signifie AEP ?","answers":["Assainissement des Eaux Pluviales","Adduction d’Eau Potable","Association des Entreprises de Plomberie","Appareillage Électrique de Protection"],"correct":1},{"q":"Pourquoi protéger les appareillages de fontainerie contre le gel ?","answers":["Pour l’esthétique","Pour éviter les ruptures et dysfonctionnements","Ce n’est pas nécessaire au Sénégal","Uniquement en hiver en Europe"],"correct":1},{"q":"La fonte ductile est surtout utilisée pour :","answers":["Les réseaux secondaires uniquement","Les réseaux principaux (robustesse)","Les branchements intérieurs uniquement","Les regards uniquement"],"correct":1},{"q":"Sur un branchement AEP, l’étanchéité doit être :","answers":["Approximative","Parfaite","Optionnelle","Vérifiée uniquement après 1 an"],"correct":1},{"q":"Avant la mise en service d’un réseau d’eau potable, que doit-on faire ?","answers":["Uniquement un rinçage","Rinçage, désinfection et essais de pression","Un simple contrôle visuel","Ouvrir toutes les vannes immédiatement"],"correct":1},{"q":"Pourquoi réaliser un essai de pression ?","answers":["Pour décorer le chantier","Pour vérifier l’étanchéité du réseau","Pour mesurer la température de l’eau","Ce n’est jamais obligatoire"],"correct":1},{"q":"Que signifie ITV dans le contexte des réseaux ?","answers":["Inspection Télévisée","Intervention Technique Visuelle","Institut Technique de la Voirie","Installation de Tuyaux Verticaux"],"correct":0},{"q":"Les plans de récolement servent à :","answers":["Planifier les congés","Documenter l’ouvrage tel qu’il a été réalisé","Commander les matériaux","Remplacer les plans d’exécution dès le début"],"correct":1},{"q":"Peut-on mettre en service un réseau d’eau potable sans essais validés ?","answers":["Oui, toujours","Non, jamais","Seulement le week-end","Uniquement pour les petits diamètres"],"correct":1}]}')
